insert into suite_context values ('org_a','cccccccc-cccc-cccc-cccc-cccccccccccc'),('org_b','99999999-dddd-dddd-dddd-dddddddddddd'),('manager_a','cccccccc-0000-0000-0000-000000000010'),('manager_other','cccccccc-0000-0000-0000-000000000011'),('employee_direct','cccccccc-0000-0000-0000-000000000001'),('employee_other','cccccccc-0000-0000-0000-000000000002'),('employee_self','cccccccc-0000-0000-0000-000000000003'),('employee_b','99999999-0000-0000-0000-000000000001'),('signal_direct','cccccccc-0000-0000-0000-000000000020'),('signal_other','cccccccc-0000-0000-0000-000000000021'),('signal_self','cccccccc-0000-0000-0000-000000000022'),('signal_restricted','cccccccc-0000-0000-0000-000000000023'),('signal_sensitive','cccccccc-0000-0000-0000-000000000024'),('signal_org','cccccccc-0000-0000-0000-000000000025'),('signal_b','99999999-0000-0000-0000-000000000020'),('evidence_a','cccccccc-0000-0000-0000-000000000030'),('recommendation_a','cccccccc-0000-0000-0000-000000000031'),('intervention_a','cccccccc-0000-0000-0000-000000000032'),('action_a','cccccccc-0000-0000-0000-000000000033'),('outcome_a','cccccccc-0000-0000-0000-000000000034'),('source_a','cccccccc-0000-0000-0000-000000000040'),('source_archived','cccccccc-0000-0000-0000-000000000048'),('source_b','99999999-0000-0000-0000-000000000040'),('doc_org','cccccccc-0000-0000-0000-000000000041'),('doc_management','cccccccc-0000-0000-0000-000000000042'),('doc_restricted','cccccccc-0000-0000-0000-000000000043'),('doc_draft','cccccccc-0000-0000-0000-000000000044'),('doc_archived','cccccccc-0000-0000-0000-000000000045'),('doc_future','cccccccc-0000-0000-0000-000000000046'),('doc_expired','cccccccc-0000-0000-0000-000000000047'),('doc_archived_source','cccccccc-0000-0000-0000-000000000049'),('doc_b','99999999-0000-0000-0000-000000000041');
insert into suite_context select 'user_'||row_number() over (order by created_at), id from auth.users order by created_at limit 5;
insert into public.organizations(id,name,slug,plan,status) values ((select value from suite_context where key='org_a'),'Intelligence A','intelligence-a','essencial','active'),((select value from suite_context where key='org_b'),'Intelligence B','intelligence-b','essencial','active');
insert into public.memberships(organization_id,user_id,role) values ((select value from suite_context where key='org_a'),(select value from suite_context where key='user_1'),'admin_youb'),((select value from suite_context where key='org_a'),(select value from suite_context where key='user_2'),'diretoria'),((select value from suite_context where key='org_a'),(select value from suite_context where key='user_3'),'gestor'),((select value from suite_context where key='org_a'),(select value from suite_context where key='user_4'),'colaborador'),((select value from suite_context where key='org_a'),(select value from suite_context where key='user_5'),'rh');
insert into public.employees(id,organization_id,auth_user_id,full_name,email,manager_employee_id) values ((select value from suite_context where key='manager_a'),(select value from suite_context where key='org_a'),(select value from suite_context where key='user_3'),'Manager A','manager-a@example.invalid',null),((select value from suite_context where key='manager_other'),(select value from suite_context where key='org_a'),(select value from suite_context where key='user_1'),'Manager Other','manager-other@example.invalid',null),((select value from suite_context where key='employee_direct'),(select value from suite_context where key='org_a'),null,'Direct report','direct@example.invalid',(select value from suite_context where key='manager_a')),((select value from suite_context where key='employee_other'),(select value from suite_context where key='org_a'),null,'Outside scope','other@example.invalid',(select value from suite_context where key='manager_other')),((select value from suite_context where key='employee_self'),(select value from suite_context where key='org_a'),(select value from suite_context where key='user_4'),'Employee Self','self@example.invalid',(select value from suite_context where key='manager_a')),((select value from suite_context where key='employee_b'),(select value from suite_context where key='org_b'),null,'Employee B','employee-b@example.invalid',null);
