insert into public.intelligence_recommendations(id,organization_id,employee_id,title) values ((select value from suite_context where key='recommendation_a'),(select value from suite_context where key='org_a'),(select value from suite_context where key='employee_direct'),'Fixture recommendation');
insert into public.intelligence_interventions(id,organization_id,recommendation_id,employee_id,intervention_type,title) values ((select value from suite_context where key='intervention_a'),(select value from suite_context where key='org_a'),(select value from suite_context where key='recommendation_a'),(select value from suite_context where key='employee_direct'),'fixture','Fixture intervention');
insert into public.intelligence_actions(id,organization_id,intervention_id,action_type,title,assignee_employee_id) values ((select value from suite_context where key='action_a'),(select value from suite_context where key='org_a'),(select value from suite_context where key='intervention_a'),'fixture','Fixture action',(select value from suite_context where key='employee_direct'));
insert into public.intelligence_outcomes(id,organization_id,intervention_id,action_id,outcome_type) values ((select value from suite_context where key='outcome_a'),(select value from suite_context where key='org_a'),(select value from suite_context where key='intervention_a'),(select value from suite_context where key='action_a'),'fixture');
insert into public.knowledge_sources(id,organization_id,source_type,name,access_level) values ((select value from suite_context where key='source_a'),(select value from suite_context where key='org_a'),'policy','Source A','organization'),((select value from suite_context where key='source_archived'),(select value from suite_context where key='org_a'),'policy','Archived source','organization'),((select value from suite_context where key='source_b'),(select value from suite_context where key='org_b'),'policy','Source B','organization');
