insert into public.knowledge_documents(id,organization_id,knowledge_source_id,document_type,title,status,valid_from,valid_until,access_level) values ((select value from suite_context where key='doc_org'),(select value from suite_context where key='org_a'),(select value from suite_context where key='source_a'),'policy','Organization published','published',null,null,'organization'),((select value from suite_context where key='doc_management'),(select value from suite_context where key='org_a'),(select value from suite_context where key='source_a'),'policy','Management published','published','2020-01-01','2099-01-01','management'),((select value from suite_context where key='doc_restricted'),(select value from suite_context where key='org_a'),(select value from suite_context where key='source_a'),'policy','Restricted published','published',null,null,'restricted'),((select value from suite_context where key='doc_draft'),(select value from suite_context where key='org_a'),(select value from suite_context where key='source_a'),'policy','Draft','draft',null,null,'organization'),((select value from suite_context where key='doc_archived'),(select value from suite_context where key='org_a'),(select value from suite_context where key='source_a'),'policy','Archived','archived',null,null,'organization'),((select value from suite_context where key='doc_future'),(select value from suite_context where key='org_a'),(select value from suite_context where key='source_a'),'policy','Future','published','2099-01-01',null,'organization'),((select value from suite_context where key='doc_expired'),(select value from suite_context where key='org_a'),(select value from suite_context where key='source_a'),'policy','Expired','published',null,'2020-01-01','organization'),((select value from suite_context where key='doc_archived_source'),(select value from suite_context where key='org_a'),(select value from suite_context where key='source_archived'),'policy','Document from archived source','published',null,null,'organization'),((select value from suite_context where key='doc_b'),(select value from suite_context where key='org_b'),(select value from suite_context where key='source_b'),'policy','Organization B','published',null,null,'organization');
insert into public.intelligence_recommendation_evidence(organization_id,recommendation_id,evidence_id) values ((select value from suite_context where key='org_a'),(select value from suite_context where key='recommendation_a'),(select value from suite_context where key='evidence_a'));
create or replace function pg_temp.try_cross_tenant_signal() returns boolean language plpgsql security invoker as $$ begin begin insert into public.intelligence_signals(organization_id,employee_id,signal_type,source_type) values ((select value from suite_context where key='org_a'),(select value from suite_context where key='employee_b'),'cross','test'); return true; exception when others then return false; end; end; $$;
create or replace function pg_temp.try_insert_signal(target_org uuid, target_employee uuid) returns boolean language plpgsql security invoker as $$ declare inserted_id uuid; begin begin insert into public.intelligence_signals(organization_id,employee_id,signal_type,source_type) values (target_org,target_employee,'authorization-probe','test') returning id into inserted_id; delete from public.intelligence_signals where id=inserted_id; return true; exception when others then return false; end; end; $$;
create or replace function pg_temp.try_update_signal(target_signal uuid) returns boolean language plpgsql security invoker as $$ begin begin update public.intelligence_signals set context = context || jsonb_build_object('authorization_probe', true) where id=target_signal; if not found then return false; end if; return true; exception when others then return false; end; end; $$;
create or replace function pg_temp.try_collaborator_insert(kind text) returns boolean language plpgsql security invoker as $$ begin begin if kind='recommendation' then insert into public.intelligence_recommendations(organization_id,employee_id,title) values ((select value from suite_context where key='org_a'),(select value from suite_context where key='employee_self'),'unauthorized'); elsif kind='evidence' then insert into public.intelligence_evidence(organization_id,signal_id,evidence_type,summary,source_type) values ((select value from suite_context where key='org_a'),(select value from suite_context where key='signal_self'),'unauthorized','unauthorized','test'); elsif kind='intervention' then insert into public.intelligence_interventions(organization_id,employee_id,intervention_type,title) values ((select value from suite_context where key='org_a'),(select value from suite_context where key='employee_self'),'unauthorized','unauthorized'); else insert into public.intelligence_outcomes(organization_id,outcome_type) values ((select value from suite_context where key='org_a'),'unauthorized'); end if; return true; exception when others then return false; end; end; $$;
create or replace function pg_temp.try_valid_signal_families() returns boolean language plpgsql security invoker as $$ declare family text; begin foreach family in array array['performance','development','leadership','experience','talent','work','knowledge','organization'] loop insert into public.intelligence_signals(organization_id,signal_type,signal_family,source_type) values ((select value from suite_context where key='org_a'),'valid-'||family,family,'test'); end loop; return true; exception when others then return false; end; $$;
create or replace function pg_temp.try_invalid_signal_family() returns boolean language plpgsql security invoker as $$ begin begin insert into public.intelligence_signals(organization_id,signal_type,signal_family,source_type) values ((select value from suite_context where key='org_a'),'invalid','invalid','test'); return true; exception when others then return false; end; end; $$;
create or replace function pg_temp.try_invalid_signal_status() returns boolean language plpgsql security invoker as $$ begin begin insert into public.intelligence_signals(organization_id,signal_type,status,source_type) values ((select value from suite_context where key='org_a'),'invalid','received','test'); return true; exception when others then return false; end; end; $$;
create or replace function pg_temp.try_invalid_signal_window() returns boolean language plpgsql security invoker as $$ begin begin insert into public.intelligence_signals(organization_id,signal_type,window_start,window_end,source_type) values ((select value from suite_context where key='org_a'),'invalid','2026-09-02','2026-09-01','test'); return true; exception when others then return false; end; end; $$;
create or replace function pg_temp.try_invalid_evidence_relation() returns boolean language plpgsql security invoker as $$ begin begin insert into public.intelligence_evidence(organization_id,signal_id,evidence_type,summary,relation,source_type) values ((select value from suite_context where key='org_a'),(select value from suite_context where key='signal_direct'),'documented','invalid','invalid','test'); return true; exception when others then return false; end; end; $$;
create or replace function pg_temp.try_evidence_relations() returns boolean language plpgsql security invoker as $$ begin begin insert into public.intelligence_evidence(organization_id,signal_id,evidence_type,summary,relation,independence_group,source_type) values ((select value from suite_context where key='org_a'),(select value from suite_context where key='signal_direct'),'quantitative','supports','supports','survey-a','test'),((select value from suite_context where key='org_a'),(select value from suite_context where key='signal_direct'),'qualitative','contradicts','contradicts','survey-a','test'),((select value from suite_context where key='org_a'),(select value from suite_context where key='signal_direct'),'documented','neutral','neutral','interview-b','test'); return (select count(*) >= 3 from public.intelligence_evidence where signal_id=(select value from suite_context where key='signal_direct') and independence_group in ('survey-a','interview-b')); exception when others then return false; end; end; $$;
set local role authenticated;
select set_config('request.jwt.claim.sub',(select value::text from suite_context where key='user_1'),true);
select pg_temp.try_valid_signal_families() as valid_families_accepted;
select pg_temp.try_evidence_relations() as evidence_relations_and_independence_group_persist;
select 'admin_youb' as role, jsonb_build_object('admin_write_same_tenant',pg_temp.try_insert_signal((select value from suite_context where key='org_a'),(select value from suite_context where key='employee_direct')),'admin_other_tenant_write_denied',not pg_temp.try_insert_signal((select value from suite_context where key='org_b'),(select value from suite_context where key='employee_b')),'tenant_a_visible',(select count(*)=14 from public.intelligence_signals where organization_id=(select value from suite_context where key='org_a')),'valid_families_accepted',(select count(*)=8 from public.intelligence_signals where organization_id=(select value from suite_context where key='org_a') and signal_family is not null),'invalid_family_rejected',not pg_temp.try_invalid_signal_family(),'invalid_status_rejected',not pg_temp.try_invalid_signal_status(),'invalid_window_rejected',not pg_temp.try_invalid_signal_window(),'invalid_evidence_relation_rejected',not pg_temp.try_invalid_evidence_relation(),'evidence_relations_and_independence_group_persist',(select count(*)>=3 from public.intelligence_evidence where signal_id=(select value from suite_context where key='signal_direct') and relation in ('supports','contradicts','neutral') and independence_group is not null),'tenant_b_hidden',(select count(*)=0 from public.intelligence_signals where organization_id=(select value from suite_context where key='org_b')),'official_knowledge_only',(select count(*)=3 from public.knowledge_documents d join public.knowledge_sources s on s.id=d.knowledge_source_id where d.organization_id=(select value from suite_context where key='org_a') and s.status='active' and d.status='published' and (d.valid_from is null or d.valid_from<=current_date) and (d.valid_until is null or d.valid_until>current_date)),'tenant_b_knowledge_hidden',(select count(*)=0 from public.knowledge_documents where organization_id=(select value from suite_context where key='org_b'))) as assertions;
select set_config('request.jwt.claim.sub',(select value::text from suite_context where key='user_2'),true);
select 'diretoria' as role, jsonb_build_object('diretoria_cannot_insert_signal_directly',not pg_temp.try_insert_signal((select value from suite_context where key='org_a'),(select value from suite_context where key='employee_direct')),'diretoria_cannot_update_signal_directly',not pg_temp.try_update_signal((select value from suite_context where key='signal_direct')),'tenant_a_visible',(select count(*)=13 from public.intelligence_signals where organization_id=(select value from suite_context where key='org_a')),'tenant_b_hidden',(select count(*)=0 from public.intelligence_signals where organization_id=(select value from suite_context where key='org_b')),'organization_and_management_knowledge_visible',(select count(*)=2 from public.knowledge_documents d join public.knowledge_sources s on s.id=d.knowledge_source_id where d.organization_id=(select value from suite_context where key='org_a') and s.status='active' and d.status='published' and (d.valid_from is null or d.valid_from<=current_date) and (d.valid_until is null or d.valid_until>current_date) and d.access_level in ('organization','management')),'restricted_knowledge_hidden',(select count(*)=0 from public.knowledge_documents where organization_id=(select value from suite_context where key='org_a') and access_level='restricted')) as assertions;
select set_config('request.jwt.claim.sub',(select value::text from suite_context where key='user_5'),true);
select 'rh' as role, jsonb_build_object('rh_write_same_tenant',pg_temp.try_insert_signal((select value from suite_context where key='org_a'),(select value from suite_context where key='employee_direct')),'rh_other_tenant_write_denied',not pg_temp.try_insert_signal((select value from suite_context where key='org_b'),(select value from suite_context where key='employee_b')),'tenant_a_visible',(select count(*)=14 from public.intelligence_signals where organization_id=(select value from suite_context where key='org_a')),'tenant_b_hidden',(select count(*)=0 from public.intelligence_signals where organization_id=(select value from suite_context where key='org_b')),'restricted_knowledge_visible',(select count(*)=1 from public.knowledge_documents where organization_id=(select value from suite_context where key='org_a') and access_level='restricted')) as assertions;
select set_config('request.jwt.claim.sub',(select value::text from suite_context where key='user_3'),true);
select 'gestor' as role, jsonb_build_object('manager_cannot_insert_signal_directly',not pg_temp.try_insert_signal((select value from suite_context where key='org_a'),(select value from suite_context where key='employee_direct')),'manager_cannot_update_signal_directly',not pg_temp.try_update_signal((select value from suite_context where key='signal_direct')),'direct_subordinate_visible',(select count(*)=1 from public.intelligence_signals where id=(select value from suite_context where key='signal_direct')),'outside_scope_hidden',(select count(*)=0 from public.intelligence_signals where id=(select value from suite_context where key='signal_other')),'tenant_b_hidden',(select count(*)=0 from public.intelligence_signals where organization_id=(select value from suite_context where key='org_b')),'aggregate_organization_signal_hidden',(select count(*)=0 from public.intelligence_signals where id=(select value from suite_context where key='signal_org')),'highly_sensitive_signal_hidden',(select count(*)=0 from public.intelligence_signals where id=(select value from suite_context where key='signal_sensitive')),'management_knowledge_visible',(select count(*)=1 from public.knowledge_documents where organization_id=(select value from suite_context where key='org_a') and access_level='management' and status='published')) as assertions;
select set_config('request.jwt.claim.sub',(select value::text from suite_context where key='user_4'),true);
select 'colaborador' as role, jsonb_build_object('collaborator_cannot_insert_signal',not pg_temp.try_insert_signal((select value from suite_context where key='org_a'),(select value from suite_context where key='employee_self')),'collaborator_cannot_update_signal',not pg_temp.try_update_signal((select value from suite_context where key='signal_self')),'own_signal_visible',(select count(*)=1 from public.intelligence_signals where id=(select value from suite_context where key='signal_self')),'direct_report_signal_hidden',(select count(*)=0 from public.intelligence_signals where id=(select value from suite_context where key='signal_direct')),'tenant_b_hidden',(select count(*)=0 from public.intelligence_signals where organization_id=(select value from suite_context where key='org_b')),'aggregate_organization_signal_hidden',(select count(*)=0 from public.intelligence_signals where id=(select value from suite_context where key='signal_org')),'restricted_signal_hidden',(select count(*)=0 from public.intelligence_signals where id=(select value from suite_context where key='signal_restricted')),'highly_sensitive_signal_hidden',(select count(*)=0 from public.intelligence_signals where id=(select value from suite_context where key='signal_sensitive')),'recommendation_insert_denied',not pg_temp.try_collaborator_insert('recommendation'),'evidence_insert_denied',not pg_temp.try_collaborator_insert('evidence'),'intervention_insert_denied',not pg_temp.try_collaborator_insert('intervention'),'outcome_insert_denied',not pg_temp.try_collaborator_insert('outcome'),'document_from_archived_source_hidden',(select count(*)=0 from public.knowledge_documents d join public.knowledge_sources s on s.id=d.knowledge_source_id where d.id=(select value from suite_context where key='doc_archived_source') and d.status='published' and s.status='active'),'only_current_official_org_doc_visible',(select count(*)=1 from public.knowledge_documents d join public.knowledge_sources s on s.id=d.knowledge_source_id where d.organization_id=(select value from suite_context where key='org_a') and s.status='active' and d.status='published' and (d.valid_from is null or d.valid_from<=current_date) and (d.valid_until is null or d.valid_until>current_date) and d.access_level='organization'),'no_draft_or_archived_in_official_query',(select count(*)=0 from public.knowledge_documents where organization_id=(select value from suite_context where key='org_a') and status in ('draft','archived'))) as assertions;
reset role;
select jsonb_build_object('cross_tenant_composite_fk_denied',not pg_temp.try_cross_tenant_signal()) as integrity_assertions;
rollback;
